-- 2026-10-24d: corrects the MP Background timeline for Irene Campbell (member_id 5145) only (owner's standing approval,
-- 24 Oct 2026). The 24c timeline cited an Arran Banner article that now returns 404. The "Business analyst and project
-- manager" entry is removed (no working source) and the candidate entry now cites the LabourList candidate selections
-- list. The array (6 entries) is copied exactly from the corrected data file (not committed) and passed
-- lib/background-timeline.ts validate(). background_last_checked stays 2026-10-24.
-- The guard fails unless 5145 held exactly the 24c value beforehand, exactly 1 row changes, the other 9 pilot
-- timelines are unchanged (md5), and every row outside the pilot still has a NULL timeline.
-- Undo: 2026-10-24d-UNDO.sql (restores the 24c value for 5145).
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL lock_timeout = '10s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id = 5145) <> 1 THEN RAISE EXCEPTION 'expected 1 biography row for 5145'; END IF;
  IF (SELECT background_timeline FROM public.mp_biography WHERE member_id = 5145) IS DISTINCT FROM $bt$[{"phase": "education", "start": null, "end": null, "title": "Secondary school", "organisation": "Auchenharvie Academy, Saltcoats", "detail": null, "source": {"title": "Wikipedia: Irene Campbell", "url": "https://en.wikipedia.org/wiki/Irene_Campbell"}}, {"phase": "career", "start": null, "end": null, "title": "Began working life in London", "organisation": null, "detail": "She moved to London in the 1980s, when jobs were scarce in North Ayrshire.", "source": {"title": "Hansard: maiden speech, 6 November 2024", "url": "https://hansard.parliament.uk/commons/2024-11-06/debates/DBE9C141-29E1-4666-B0D1-CF616C409D66/BudgetResolutions"}}, {"phase": "career", "start": null, "end": null, "title": "Business analyst and project manager", "organisation": "Civil service", "detail": null, "source": {"title": "Arran Banner: Irene is Labour general election candidate (19 January 2024)", "url": "https://www.arranbanner.co.uk/2024/01/19/irene-is-labour-general-election-candidate/"}}, {"phase": "career", "start": null, "end": null, "title": "Senior roles, including programme management", "organisation": "NHS", "detail": null, "source": {"title": "LabourList: Labour parliamentary candidate selections", "url": "https://labourlist.org/2024/06/our-rolling-list-of-labour-parliamentary-candidate-selections/"}}, {"phase": "career", "start": "2009-06", "end": "2020-11", "title": "Board member, later chair", "organisation": "North Ayrshire Women's Aid", "detail": null, "source": {"title": "Companies House: North Ayrshire Women's Aid (SC357590) officers", "url": "https://find-and-update.company-information.service.gov.uk/company/SC357590/officers"}}, {"phase": "career", "start": null, "end": "present", "title": "Founder member and chair", "organisation": "SPLASH, Saltcoats outdoor pool campaign", "detail": "An unpaid role.", "source": {"title": "UK Parliament: Register of Members' Financial Interests, Irene Campbell", "url": "https://members.parliament.uk/member/5145/registeredinterests"}}, {"phase": "politics", "start": "2024-01", "end": "2024-07", "title": "Labour candidate, North Ayrshire and Arran", "organisation": "Scottish Labour", "detail": null, "source": {"title": "Arran Banner: Irene is Labour general election candidate (19 January 2024)", "url": "https://www.arranbanner.co.uk/2024/01/19/irene-is-labour-general-election-candidate/"}}]$bt$::jsonb THEN
    RAISE EXCEPTION '5145 does not hold the 24c timeline';
  END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th FROM public.mp_biography b;

UPDATE public.mp_biography SET background_timeline = $bt$[{"phase": "education", "start": null, "end": null, "title": "Secondary school", "organisation": "Auchenharvie Academy, Saltcoats", "detail": null, "source": {"title": "Wikipedia: Irene Campbell", "url": "https://en.wikipedia.org/wiki/Irene_Campbell"}}, {"phase": "career", "start": null, "end": null, "title": "Began working life in London", "organisation": null, "detail": "She moved to London in the 1980s, when jobs were scarce in North Ayrshire.", "source": {"title": "Hansard: maiden speech, 6 November 2024", "url": "https://hansard.parliament.uk/commons/2024-11-06/debates/DBE9C141-29E1-4666-B0D1-CF616C409D66/BudgetResolutions"}}, {"phase": "career", "start": null, "end": null, "title": "Senior roles, including programme management", "organisation": "NHS", "detail": null, "source": {"title": "LabourList: Labour parliamentary candidate selections", "url": "https://labourlist.org/2024/06/our-rolling-list-of-labour-parliamentary-candidate-selections/"}}, {"phase": "career", "start": "2009-06", "end": "2020-11", "title": "Board member, later chair", "organisation": "North Ayrshire Women's Aid", "detail": null, "source": {"title": "Companies House: North Ayrshire Women's Aid (SC357590) officers", "url": "https://find-and-update.company-information.service.gov.uk/company/SC357590/officers"}}, {"phase": "career", "start": null, "end": "present", "title": "Founder member and chair", "organisation": "SPLASH, Saltcoats outdoor pool campaign", "detail": "An unpaid role.", "source": {"title": "UK Parliament: Register of Members' Financial Interests, Irene Campbell", "url": "https://members.parliament.uk/member/5145/registeredinterests"}}, {"phase": "politics", "start": null, "end": "2024-07", "title": "Labour candidate, North Ayrshire and Arran", "organisation": "Scottish Labour", "detail": null, "source": {"title": "LabourList: Labour parliamentary candidate selections", "url": "https://labourlist.org/2024/06/our-rolling-list-of-labour-parliamentary-candidate-selections/"}}]$bt$ WHERE member_id = 5145;

DO $$
DECLARE
  changed integer;
  pilot_changed integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  IF changed <> 1 THEN RAISE EXCEPTION 'expected exactly 1 row changed, got %', changed; END IF;
  IF (SELECT background_timeline FROM public.mp_biography WHERE member_id = 5145) IS DISTINCT FROM $bt$[{"phase": "education", "start": null, "end": null, "title": "Secondary school", "organisation": "Auchenharvie Academy, Saltcoats", "detail": null, "source": {"title": "Wikipedia: Irene Campbell", "url": "https://en.wikipedia.org/wiki/Irene_Campbell"}}, {"phase": "career", "start": null, "end": null, "title": "Began working life in London", "organisation": null, "detail": "She moved to London in the 1980s, when jobs were scarce in North Ayrshire.", "source": {"title": "Hansard: maiden speech, 6 November 2024", "url": "https://hansard.parliament.uk/commons/2024-11-06/debates/DBE9C141-29E1-4666-B0D1-CF616C409D66/BudgetResolutions"}}, {"phase": "career", "start": null, "end": null, "title": "Senior roles, including programme management", "organisation": "NHS", "detail": null, "source": {"title": "LabourList: Labour parliamentary candidate selections", "url": "https://labourlist.org/2024/06/our-rolling-list-of-labour-parliamentary-candidate-selections/"}}, {"phase": "career", "start": "2009-06", "end": "2020-11", "title": "Board member, later chair", "organisation": "North Ayrshire Women's Aid", "detail": null, "source": {"title": "Companies House: North Ayrshire Women's Aid (SC357590) officers", "url": "https://find-and-update.company-information.service.gov.uk/company/SC357590/officers"}}, {"phase": "career", "start": null, "end": "present", "title": "Founder member and chair", "organisation": "SPLASH, Saltcoats outdoor pool campaign", "detail": "An unpaid role.", "source": {"title": "UK Parliament: Register of Members' Financial Interests, Irene Campbell", "url": "https://members.parliament.uk/member/5145/registeredinterests"}}, {"phase": "politics", "start": null, "end": "2024-07", "title": "Labour candidate, North Ayrshire and Arran", "organisation": "Scottish Labour", "detail": null, "source": {"title": "LabourList: Labour parliamentary candidate selections", "url": "https://labourlist.org/2024/06/our-rolling-list-of-labour-parliamentary-candidate-selections/"}}]$bt$::jsonb THEN
    RAISE EXCEPTION '5145 does not hold the corrected timeline';
  END IF;
  IF (SELECT jsonb_array_length(background_timeline) FROM public.mp_biography WHERE member_id = 5145) <> 6 THEN RAISE EXCEPTION '5145 entry count is not 6'; END IF;
  SELECT count(*) INTO pilot_changed FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id IN (4483, 1427, 5091, 4356, 400, 5449, 5068, 5145, 5284, 5309) AND b.member_id <> 5145 AND md5(coalesce(b.background_timeline::text, '')) IS DISTINCT FROM o.th;
  IF pilot_changed <> 0 THEN RAISE EXCEPTION '% other pilot timelines changed', pilot_changed; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (4483, 1427, 5091, 4356, 400, 5449, 5068, 5145, 5284, 5309) AND jsonb_typeof(background_timeline) = 'array' AND background_last_checked = DATE '2026-10-24') <> 10 THEN
    RAISE EXCEPTION 'expected 10 pilot rows with a timeline';
  END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id NOT IN (4483, 1427, 5091, 4356, 400, 5449, 5068, 5145, 5284, 5309) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a row outside the pilot has a timeline'; END IF;
END $$;

COMMIT;
